-- cdk_gl_account_master (gl-account-master) -- GL Account Master
-- Chart of Accounts
-- SAP analogue: SKA1 (G/L Account Master, Chart of Accounts) / SKB1 (Company Code Data)
-- grain: one row per GL account number (+ department suffix) per rooftop
-- api reach: none
-- generated by schema/bin/gen_ddl.py from contract EgD-CDK-FIELDS-v2 -- do not hand-edit, regenerate instead

CREATE TABLE IF NOT EXISTS cdk_gl_account_master (
    gl_account_number varchar(6) NOT NULL,
    department_suffix varchar(2),
    sub_account_letter varchar(1),
    account_name varchar(60),
    account_type varchar(32),
    normal_balance varchar(32),
    is_control_account boolean,
    is_department_bound boolean,
    is_active boolean,
    _rooftop_id varchar(20),
    _extracted_at timestamptz,
    _source_route varchar(16),
    _batch_id varchar(64),
    PRIMARY KEY (gl_account_number)
);

-- Column comments (dealer-language label + confidence mark: [D]=documented [I]=inferred [U]=unverified)
COMMENT ON COLUMN cdk_gl_account_master.gl_account_number IS '[D] GL Account Number (base)';
COMMENT ON COLUMN cdk_gl_account_master.department_suffix IS '[D] Department Suffix';
COMMENT ON COLUMN cdk_gl_account_master.sub_account_letter IS '[D] Sub-Account Letter Suffix';
COMMENT ON COLUMN cdk_gl_account_master.account_name IS '[D] Account Name / Description';
COMMENT ON COLUMN cdk_gl_account_master.account_type IS '[D] Account Type (values: ASSET=200-series: Assets; LIAB_EQUITY=300-series: Liabilities/Equity; SALES=400-series: Sales; COGS=600-series: Cost of Goods Sold; LEASE_RENTAL_COST=700-series: Lease/Rental Cost; OTHER_INCOME_FI=800/900-series: Other Income/F&I)';
COMMENT ON COLUMN cdk_gl_account_master.normal_balance IS '[I] Normal Balance Side (values: DEBIT=Normal debit balance (assets, COGS, lease/rental cost); CREDIT=Normal credit balance (liabilities, equity, sales, other income))';
COMMENT ON COLUMN cdk_gl_account_master.is_control_account IS '[D] Reconciliation/Control Account Flag';
COMMENT ON COLUMN cdk_gl_account_master.is_department_bound IS '[I] Department-Bound Flag';
COMMENT ON COLUMN cdk_gl_account_master.is_active IS '[U] Active Flag';
COMMENT ON COLUMN cdk_gl_account_master._rooftop_id IS '[D] which rooftop/store this extracted row belongs to';
COMMENT ON COLUMN cdk_gl_account_master._extracted_at IS '[D] when this row was pulled from CDK by the extract harness';
COMMENT ON COLUMN cdk_gl_account_master._source_route IS '[D] which of the three extract routes produced this row: fortellis | export | screen';
COMMENT ON COLUMN cdk_gl_account_master._batch_id IS '[D] the extract run/batch identifier this row landed with';
